"""Emission compliance tests for frontend (auto-generated by pact)."""

from frontend.frontend import Frontend


class TestEmissionCompliance:
    """Verify frontend emits structured events correctly."""

    def _make_handler(self):
        events = []
        return events, lambda event: events.append(event)

    def test_fetchTasks_emits_events(self):
        """Method fetchTasks emits invoked and completed events."""
        events, handler = self._make_handler()
        obj = Frontend(event_handler=handler)
        try:
            obj.fetchTasks()
        except (TypeError, Exception):
            pass
        invoked = [e for e in events if e.get("event") == "invoked"]
        completed = [e for e in events if e.get("event") in ("completed", "error")]
        assert len(invoked) >= 1, 'No invoked event for fetchTasks'
        assert len(completed) >= 1, 'No completed/error event for fetchTasks'
        assert invoked[0].get("pact_key") == "PACT:frontend:fetchTasks"
        assert isinstance(invoked[0].get("input_classification"), list)

