    def test_pact_key_format(self):
        """All emitted events have correctly formatted PACT keys."""
        events, handler = self._make_handler()
        obj = Frontend(event_handler=handler)
        try:
            obj.fetchTasks()
        except (TypeError, Exception):
            pass
        try:
            obj.createTask()
        except (TypeError, Exception):
            pass
        try:
            obj.updateTask()
        except (TypeError, Exception):
            pass
        try:
            obj.deleteTask()
        except (TypeError, Exception):
            pass
        try:
            obj.healthCheck()
        except (TypeError, Exception):
            pass
        try:
            obj.App.handleCreate()
        except (TypeError, Exception):
            pass
        try:
            obj.App.handleUpdate()
        except (TypeError, Exception):
            pass
        try:
            obj.App.handleDelete()
        except (TypeError, Exception):
            pass
        try:
            obj.App.useEffectFetchOnMount()
        except (TypeError, Exception):
            pass
        try:
            obj.resolveBaseUrl()
        except (TypeError, Exception):
            pass
        try:
            obj.parseErrorResponse()
        except (TypeError, Exception):
            pass
        for event in events:
            key = event.get("pact_key", "")
            assert key.startswith("PACT:frontend:"), f"Bad pact_key: {key}"

